  if(foodItems.length)cats.push({name:'食物',items:foodItems});
  if(bodyTrainBonusHP>0)cats.push({name:'练体',items:['生命练体 Lv.'+bodyTrain.hp.lv+' +'+bodyTrainBonusHP]});
  var colItems=[];
