function useItem(arr,idx,qty){qty=qty||1;if(idx>=arr.length)return;var entry=arr[idx];if(entry.id==='faintSpirit'){for(var _u=0;_u<qty;_u++){if(findSlot(arr,'faintSpirit')<0)break;var bonus=Math.min(100,Math.floor(exp*0.05));setExp(exp+applyCultivateBonus(bonus));removeOne(arr,'faintSpirit');}saveGame();return true;}if(entry.id==='herbPill'){var recipe=RECIPES.herbPill;var _max=recipe.maxCraft?recipe.maxCraft-craftStats.herbPill.used:qty;var _use=Math.min(qty,_max);for(var _u=0;_u<_use;_u++){if(findSlot(arr,'herbPill')<0)break;bonusHP+=recipe.effects.hpMax;bonusATK+=recipe.effects.atk;bonusDEF+=recipe.effects.def;craftStats.herbPill.used++;removeOne(arr,'herbPill');}refreshMaxHP();saveGame();return true;}if(entry.id==='mosquitoPill'){var recipe2=RECIPES.mosquitoPill;var _max2=recipe2.maxCraft?recipe2.maxCraft-craftStats.mosquitoPill.used:qty;var _use2=Math.min(qty,_max2);for(var _u=0;_u<_use2;_u++){if(findSlot(arr,'mosquitoPill')<0)break;bonusHP+=recipe2.effects.hpMax;bonusLifesteal+=recipe2.effects.lifestealBonus;craftStats.mosquitoPill.used++;removeOne(arr,'mosquitoPill');}refreshMaxHP();saveGame();return true;}if(entry.id==='songrongSoup'){var _sR=RECIPES.songrongSoup;var _max3=_sR.maxCraft?_sR.maxCraft-craftStats.songrongSoup.used:qty;var _use3=Math.min(qty,_max3);for(var _u=0;_u<_use3;_u++){if(findSlot(arr,'songrongSoup')<0)break;bonusHP+=_sR.effects.hpMax;craftStats.songrongSoup.used++;removeOne(arr,'songrongSoup');}refreshMaxHP();saveGame();return true;}if(entry.id==='lingzhiPill'){var _lR=RECIPES.lingzhiPill;var _max4=_lR.maxCraft?_lR.maxCraft-craftStats.lingzhiPill.used:qty;var _use4=Math.min(qty,_max4);for(var _u=0;_u<_use4;_u++){if(findSlot(arr,'lingzhiPill')<0)break;bonusHP+=_lR.effects.hpMax;craftStats.lingzhiPill.used++;removeOne(arr,'lingzhiPill');}refreshMaxHP();saveGame();return true;}var _skillBooks={manualJiXue:'jiXue',manualGeDang:'geDang',manualFanTan:'fanTan',manualInsight:'insight'};if(_skillBooks[entry.id]){var sk=_skillBooks[entry.id];for(var _u=0;_u<qty;_u++){if(skills[sk]>=10)break;if(findSlot(arr,entry.id)<0)break;skills[sk]++;removeOne(arr,entry.id);}saveGame();return true;}}
