function showCraftPopup(rk){
var r=RECIPES[rk],it=ITEMS[r.resultId];var eff=[];
if(r.effects.atkPct)eff.push('攻击加成+'+r.effects.atkPct+'%');
if(r.effects.skill==='jiXue')eff.push('学习后汲血技能Lv+1');
else if(r.effects.skill==='geDang')eff.push('学习后格挡技能Lv+1');
else if(r.effects.skill==='fanTan')eff.push('学习后反弹技能Lv+1');
else if(r.effects.skill==='insight')eff.push('学习后洞察技能Lv+1');
if(r.effects.hpMax)eff.push('血量上限+'+r.effects.hpMax);
if(r.effects.atk)eff.push('攻击+'+r.effects.atk);
if(r.effects.def)eff.push('防御+'+r.effects.def);
if(r.effects.rec)eff.push('自然恢复+'+r.effects.rec);
if(r.effects.cultivateBonus)eff.push('修为获取+'+Math.round(r.effects.cultivateBonus*100)+'%');
if(r.effects.lifestealBonus)eff.push('吸血+'+(r.effects.lifestealBonus*100).toFixed(2)+'%');
var h='<div class="modal-name">'+it.name+'</div>';
h+='<div class="modal-desc">'+it.desc+'</div>';
if(eff.length)h+='<div class="modal-meta">\u6548\u679c\uff1a'+eff.join('\uff0c')+'</div>';
h+='<div class="modal-btns"><button class="btn btn-sm" id="mbCraftClose">\u5173\u95ed</button></div>';
$modalBox.innerHTML=h;$modalOverlay.classList.add('show');
document.getElementById('mbCraftClose').addEventListener('click',closeModal);
}
var SHOP_REFRESH_MS=10*60*1000;var SHOP_REFRESH_COST=5;var shopLevel={gridCount:3,rareLevel:1};var skills={insight:0};var shopSlots=[null,null,null];var shopRefreshAt=0;var shopTimer=null;var lastTravelDest='grassland';
function getCraftLevelReq(cat){return CRAFT_LEVEL_BASE[cat]*Math.pow(2,craftLevels[cat].lv-1);}function addCraftExp(cat,amount){craftLevels[cat].exp+=amount;while(craftLevels[cat].exp>=getCraftLevelReq(cat)){craftLevels[cat].exp-=getCraftLevelReq(cat);craftLevels[cat].lv++;}}var craftCategory='alchemy';
function renderCraft(){var html='<div class="craft-tabs"><button class="craft-tab'+(craftCategory==='alchemy'?' active':'')+'" data-cat="alchemy">炼丹</button><button class="craft-tab'+(craftCategory==='accessory'?' active':'')+'" data-cat="accessory">锻造</button><button class="craft-tab'+(craftCategory==='cook'?' active':'')+'" data-cat="cook">烹饪</button><button class="craft-tab'+(craftCategory==='manual'?' active':'')+'" data-cat="manual">秘籍</button><button class="craft-tab" data-cat="other">其它</button></div>';if(craftCategory==='alchemy'){html+='<div class="section-title">炼丹配方</div>'+buildRecipeRow('herbPill')+buildRecipeRow('mosquitoPill')+buildRecipeRow('lingzhiPill');}else if(craftCategory==='accessory'){html+='<div class="section-title">锻造配方</div>'+buildRecipeRow('grassKnot')+buildRecipeRow('ratSkinAmulet');}else if(craftCategory==='cook'){html+='<div class="section-title">烹饪配方</div>'+buildRecipeRow('songrongSoup');}else if(craftCategory==='manual'){html+='<div class="section-title">秘籍配方</div>'+buildRecipeRow('jiXue')+buildRecipeRow('geDang')+buildRecipeRow('fanTan')+buildRecipeRow('insight');}else html+='<div class="craft-empty">暂无配方</div>';$craftWrap.innerHTML=html;$craftWrap.querySelectorAll('.craft-tab').forEach(function(tab){tab.addEventListener('click',function(){craftCategory=tab.getAttribute('data-cat');renderCraft();});});$craftWrap.querySelectorAll('.recipe-slot').forEach(function(slot){slot.addEventListener('click',function(){var rk=slot.getAttribute('data-rk');if(!rk||!RECIPES[rk])return;showCraftPopup(rk);});});var cbs=$craftWrap.querySelectorAll('.recipe-btn[data-recipe]');cbs.forEach(function(cb){cb.addEventListener('click',function(){doCraft(cb.getAttribute('data-recipe'));});});renderCraftLevelBar();}
function renderCraftLevelBar(){var el=document.getElementById("craftLevelBar");if(!el)return;var names={alchemy:"\u70bc\u4e39",accessory:"\u953b\u9020",manual:"\u79d8\u7c4d",cook:"\u70f9\u996a"};var cat=craftCategory;if(!names[cat]){el.innerHTML="";return;}var cl=craftLevels[cat],rq=getCraftLevelReq(cat);el.innerHTML="<span class=\"attr-label\">"+names[cat]+" Lv."+cl.lv+"</span> <span class=\"attr-val\">"+cl.exp+"/"+rq+"</span>";el.onclick=function(){var old=el.querySelector(".craft-level-tip");if(old){old.remove();return;}var tip=document.createElement("div");tip.className="craft-level-tip";if(cl.lv<=1)tip.textContent="\u6682\u65e0\u52a0\u6210";else if(cat==="alchemy"&&cl.lv===2)tip.textContent="5%\u989d\u5916\u4ea7\u51fa";else tip.textContent="\u6548\u679c\u5f85\u8865\u5145";el.appendChild(tip);};}
function getBodyTrainReq(key){return 10+bodyTrain[key].lv*10;}
function renderBodyTrain(){var el=document.getElementById('bodyTrainWrap');if(!el)return;var _si=document.getElementById('stateIndicator');if(_si)_si.textContent=playerState==='bodyTrain'?'\u7ec3\u4f53\u4e2d':'';var _btargets=[{key:'hp',name:'\u751f\u547d\u7ec3\u4f53',bonus:'+5\u751f\u547d/\u7ea7'},{key:'atk',name:'\u653b\u51fb\u7ec3\u4f53',bonus:'+1\u653b\u51fb/\u7ea7'},{key:'def',name:'\u9632\u5fa1\u7ec3\u4f53',bonus:'+1\u9632\u5fa1/\u7ea7'}];var h='<div class="section-title">\u7ec3\u4f53</div>';for(var i=0;i<_btargets.length;i++){var t=_btargets[i],bt=bodyTrain[t.key],req=getBodyTrainReq(t.key),pct=Math.min(100,Math.floor(bt.exp/req*100));var isActive=bodyTrainTarget===t.key&&playerState==='bodyTrain';h+='<div class="recipe-row">';h+='<div class="recipe-slot" style="cursor:default">'+t.name+'</div>';h+='<div class="recipe-info">';h+='<div>'+t.name+' <span class="count">Lv.'+bt.lv+' '+t.bonus+'</span></div>';h+='<div style="display:flex;align-items:center;gap:8px;margin-top:4px">';h+='<div style="flex:1;height:8px;background:#eee;border-radius:4px;overflow:hidden"><div style="height:100%;width:'+pct+'%;background:#4CAF50;border-radius:4px"></div></div>';h+='<span style="font-size:12px;color:#888;white-space:nowrap">'+bt.exp+'/'+req+'</span>';h+='</div></div>';h+='<button class="recipe-btn" data-bt="'+t.key+'" style="'+(isActive?'background:#4CAF50;color:#fff':'')+'">'+(isActive?'\u7ec3\u4f53\u4e2d...':'\u5f00\u59cb')+'</button>';h+='</div>';}el.innerHTML=h;el.querySelectorAll('.recipe-btn[data-bt]').forEach(function(btn){btn.addEventListener('click',function(){var key=btn.getAttribute('data-bt');if(playerState==='bodyTrain'&&bodyTrainTarget===key){stopBodyTrain();}else{startBodyTrain(key);}});});}
function startBodyTrain(key){if(playerState==='traveling')return;if(playerState==='bodyTrain'&&bodyTrainTarget===key)return;if(playerState==='cultivating')stopCultivate();stopBodyTrain();playerState='bodyTrain';bodyTrainTarget=key;bodyTrainTimer=setInterval(function(){var bt=bodyTrain[key];bt.exp++;var req=getBodyTrainReq(key);if(bt.exp>=req){bt.exp-=req;bt.lv++;if(key==='hp'){bonusHP+=5;bodyTrainBonusHP+=5;refreshMaxHP();playerHP=playerMaxHP;}else if(key==='atk'){bonusATK+=1;bodyTrainBonusATK+=1;}else if(key==='def'){bonusDEF+=1;bodyTrainBonusDEF+=1;}}renderBodyTrain();saveGame();},5000);renderMain();renderBodyTrain();}
